import numpy as np
D=np.load('/app/runs/initial/depth_head_camera.npy')[0].astype(float)/1000
for name,(umin,umax,vmin,vmax) in {'left':(90,120,105,150),'right':(185,218,85,128),'pot':(115,190,85,165)}.items():
 a=[]
 for v in range(vmin,vmax):
  for u in range(umin,umax):
   z=D[v,u]; yy=(v-120)/358.642*z; wz=1.35-.6*yy-.8*z
   if wz>.77:
    wx=(u-160)/358.642*z-.032;wy=-.45-.8*yy+.6*z
    a.append((u,v,wx,wy,wz))
 a=np.array(a)
 print(name,len(a),'pixel range',a[:,:2].min(0),a[:,:2].max(0),'world range',a[:,2:].min(0),a[:,2:].max(0),'median',np.median(a[:,2:],axis=0))
 for v in range(vmin,vmax):
  pts=a[a[:,1]==v]
  if len(pts):print(v,','.join(map(str,pts[:,0].astype(int))))
